<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\{StockTransaction,GuestMeal,DepartmentLedger};
class ExportCenterController extends Controller { public function index(){ return view('admin.exports.index'); } private function csv($name,$headers,$rows){ return response()->streamDownload(function() use($headers,$rows){ $out=fopen('php://output','w'); fputcsv($out,$headers); foreach($rows as $r){ fputcsv($out,$r);} fclose($out); },$name,['Content-Type'=>'text/csv']); } public function stockLedger(){ $rows=StockTransaction::orderBy('txn_at')->get()->map(fn($r)=>[$r->txn_at,$r->item_id,$r->txn_type,$r->quantity,$r->unit_cost,$r->remarks]); return $this->csv('stock-ledger.csv',['txn_at','item_id','txn_type','quantity','unit_cost','remarks'],$rows);} public function guestMeals(){ $rows=GuestMeal::orderBy('meal_date')->get()->map(fn($r)=>[$r->meal_date,$r->guest_id,$r->meal_type,$r->quantity,$r->rate,$r->amount]); return $this->csv('guest-meals.csv',['meal_date','guest_id','meal_type','quantity','rate','amount'],$rows);} public function departmentLedger(){ $rows=DepartmentLedger::orderBy('entry_date')->get()->map(fn($r)=>[$r->entry_date,$r->department_id,$r->mess_id,$r->entry_type,$r->amount,$r->remarks]); return $this->csv('department-ledger.csv',['entry_date','department_id','mess_id','entry_type','amount','remarks'],$rows);} }
